    "longReadings": [
      {
        "title": "Designing AR-HUD cues for navigation without overload",
        "text": "An augmented-reality head-up display can make navigation feel natural when the cue is anchored to the road scene. The goal is not to cover the windshield with information, but to place the next action where the driver already looks. For lane-level guidance, the overlay should appear before the junction, point toward the target lane, and then fade when the maneuver is clear. Designers must check occlusion risk because a bright arrow can hide a pedestrian crossing, a traffic sign, or a vehicle edge. Focal distance also matters. If every prompt forces the driver to refocus, the display may increase visual workload instead of reducing it. A decluttered overlay protects the glance budget: one spatial cue, one short semantic label, and one stable position are usually enough. Contrast threshold and adaptive brightness should support legibility in sunlight without creating glare at night. When the situation becomes safety-critical, the priority rule should remove decorative content and keep the warning aligned with the real hazard. A useful AR-HUD experience respects driver attention, calibrates projection alignment carefully, and treats the road as the primary interface.",
        "translation": "增强现实抬头显示如果把提示锚定到道路场景中，就能让导航感觉更自然。目标不是用信息覆盖挡风玻璃，而是把下一步动作放在驾驶员已经在看的位置。对于车道级引导，叠层应在交汇处之前出现，指向目标车道，并在操作明确后淡出。设计师必须检查遮挡风险，因为明亮箭头可能遮住人行横道、交通标志或车辆边缘。焦距距离也很重要。如果每个提示都迫使驾驶员重新调焦，显示可能会增加而不是降低视觉负荷。去杂化叠层可以保护扫视预算：一个空间提示、一个简短语义标签和一个稳定位置通常就足够。对比度阈值和自适应亮度应支持阳光下的易读性，同时避免夜间眩光。当情境变成安全关键时，优先级规则应移除装饰性内容，并让警告与真实危险保持对齐。有用的 AR-HUD 体验会尊重驾驶员注意力，仔细校准投影对齐，并把道路视为主要界面。",
        "source": null
      }
    ],
