    "longReadings": [
      {
        "title": "Designing voice prompts around driver workload",
        "text": "The best cockpit voice experience is not the longest answer; it is the right interruption at the right moment. In an intelligent cockpit, contextual voice guidance must read the driving scene before it speaks. Near an intersection, the assistant may replace a full sentence with an acoustic cue and a small visual fallback. That screen should preserve dialog state, so the user can answer later without starting over. During a calm highway segment, a longer spoken explanation may be acceptable because the road demand is lower. The design rule is simple: match the message length to driver workload. If speech latency is high, the system should avoid silence and say, I am checking that request. For intent repair, the assistant should ask about the uncertain slot rather than replaying the entire command. A useful confirmation phrase names the action, the target, and the outcome, for example, I will lower the rear cabin temperature by two degrees, and you can undo it. This phrasing gives control without adding a heavy visual task. Voice interaction becomes safer when it respects timing, shows a visual fallback, and keeps every risky action reversible.",
        "translation": "最佳的座舱语音体验不是最长的回答，而是在正确时刻出现的正确打断。在智能座舱中，情境化语音引导必须先读取驾驶场景再发声。接近路口时，助手可以用声学提示和小型视觉兜底替代完整句子。该屏幕应保留对话状态，让用户稍后无需重来即可回答。在平稳的高速路段，较长的语音解释可能可以接受，因为道路需求较低。设计规则很简单：让信息长度匹配驾驶员负荷。如果语音延迟较高，系统应避免沉默，并说明“我正在检查该请求”。对于意图修复，助手应询问不确定的信息槽，而不是重放整条指令。有用的确认短语会说明动作、目标和结果，例如“我会把后排座舱温度降低两度，并且你可以撤销”。这种措辞在不增加沉重视觉任务的情况下提供控制感。当语音交互尊重时机、显示视觉兜底，并让每个高风险动作保持可撤销时，它会更安全。",
        "source": null
      }
    ],
