    "longReadings": [
      {
        "title": "Practice reading",
        "text": "When a vehicle supports assisted driving, the cockpit must help the driver understand when attention is required again. A driver monitoring system can detect long glances away from the road, closed eyes, unstable head pose, or hands that are not ready for control. However, the handoff message should not sound like a sudden alarm every time the signal changes. Good trust calibration starts by showing the automation boundary in plain language: lane markings are unclear, traffic is complex, or the system needs the driver to confirm control. The interface should combine a short spoken cue, a glanceable visual cue, and, when necessary, a haptic pulse on the wheel or seat. If the driver looks back quickly, the system can use a grace period and return to a calm status. If takeover readiness remains low, an escalation ladder should increase urgency step by step. The message has to say what changed, why it matters, and what action is expected now. This keeps mode awareness accurate without blaming the user. The goal is not to create fear. The goal is to keep the driver engaged at the right moment and to make the automation feel honest about its limits.",
        "translation": "当车辆支持辅助驾驶时，座舱必须帮助驾驶员理解什么时候需要重新注意驾驶。驾驶员监测系统可以检测长时间离开道路的视线、闭眼、不稳定的头部姿态，或尚未准备好控制车辆的双手。然而，接管提示不应在每次信号变化时都像突然警报一样响起。良好的信任校准首先要用直白语言显示自动化边界：车道线不清晰、交通复杂，或系统需要驾驶员确认控制权。界面应组合简短语音线索、可扫视视觉线索，并在必要时通过方向盘或座椅提供触觉脉冲。如果驾驶员快速看回道路，系统可以使用宽限时间并回到平静状态。如果接管准备度仍然较低，升级梯度应逐步提高紧迫性。提示必须说明发生了什么变化、为什么重要，以及现在期望什么动作。这能保持模式感知准确，同时不责备用户。目标不是制造恐惧，而是在正确时刻让驾驶员重新参与，并让自动化诚实呈现自身限制。"
      }
    ],
