    "longReadings": [
      {
        "title": "Practice reading",
        "text": "In an intelligent cockpit, feedback is not only a visual message on a screen. The driver may adjust climate control, accept a route suggestion, or use a steering-wheel shortcut while still monitoring traffic. If every action requires a long glance, the interface increases eyes-off-road time and creates unnecessary visual load. Haptic confirmation can close the interaction loop with a short pulse, a subtle vibration, or a change in button resistance. The key is to match the cue to the risk of the action. A low-risk comfort adjustment may need only micro-feedback, while a high-risk warning should combine a clear visual signal with an audible tone and stronger tactile feedback. Glanceable feedback should also show the operational state in plain language: what changed, whether the system accepted the input, and what the driver can do next. Good cockpit design builds a feedback hierarchy across channels. It avoids treating every successful tap like an urgent alert, but it also avoids silent changes that leave the driver uncertain. When haptic, visual, and audio cues work together, the cockpit can confirm actions quickly, reduce attention demand, and keep the driver's eyes closer to the road.",
        "translation": "在智能座舱中，反馈不只是屏幕上的视觉信息。驾驶员可能在观察交通的同时调节空调、接受路线建议或使用方向盘快捷操作。如果每个动作都需要长时间注视，界面就会增加离路注视时间并造成不必要的视觉负荷。触觉确认可以通过短促脉冲、细微振动或按键阻尼变化来闭合交互循环。关键是让提示强度匹配操作风险。低风险舒适性调节可能只需要微反馈，而高风险警告应结合清晰视觉信号、可听提示音和更强触觉反馈。可扫视反馈还应使用清晰语言呈现运行状态：发生了什么变化、系统是否接受输入，以及驾驶员下一步可以做什么。优秀的座舱设计会跨通道建立反馈层级，既避免把每次成功点击都做成紧急警报，也避免静默改变让驾驶员不确定。当触觉、视觉和声音线索协同工作时，座舱可以快速确认操作、降低注意力需求，并让驾驶员视线更接近道路。"
      }
    ],
